<?php require_once __DIR__.'/../api/bootstrap.php'; require_login(); $m=current_medico(); $id=(int)($_GET['id']??0); $s=db()->prepare('SELECT * FROM modelos_documento WHERE id=? AND medico_id=?'); $s->execute([$id,$m['id']]); $x=$s->fetch(); if(!$x)exit('Modelo não encontrado.'); $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$nome=trim($_POST['nome']??'');$conteudo=trim($_POST['conteudo']??'');$tipo=$_POST['tipo']??'';$ativo=!empty($_POST['ativo'])?1:0;if($nome===''||$conteudo===''||!in_array($tipo,['ATESTADO','LAUDO'],true))$err='Preencha os campos obrigatórios.';else{$q=db()->prepare('UPDATE modelos_documento SET tipo=?,nome=?,conteudo=?,ativo=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND medico_id=?');$q->execute([$tipo,$nome,$conteudo,$ativo,$id,$m['id']]);redirect_to('modelos/');}} render_header('Editar modelo'); ?><h1>Editar modelo</h1><?php if($err): ?><div class="error"><?=e($err)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="card"><div class="grid"><div><label>Tipo</label><select name="tipo"><option value="ATESTADO" <?=$x['tipo']==='ATESTADO'?'selected':''?>>Atestado</option><option value="LAUDO" <?=$x['tipo']==='LAUDO'?'selected':''?>>Laudo</option></select></div><div><label>Nome</label><input name="nome" value="<?=e($x['nome'])?>" required></div></div><label>Conteúdo</label><textarea name="conteudo" rows="18" required><?=e($x['conteudo'])?></textarea><label><input type="checkbox" name="ativo" value="1" <?=$x['ativo']?'checked':''?>> Ativo</label></div><button class="btn ok">Salvar</button></form><?php render_footer(); ?>